// Parse input parameters
const query = $json.query || $json.body?.query || '';
const maxChunks = $json.max_chunks || $json.body?.max_chunks || 5;
const temperature = $json.temperature || $json.body?.temperature || 0.7;
const filters = $json.filters || $json.body?.filters || {};
const minScore = $json.min_score || $json.body?.min_score || 0.7;

return {
  json: {
    query,
    max_chunks: maxChunks,
    include_citations: true,
    temperature,
    filters,
    min_score: minScore
  }
};

// Format response with enhanced metadata
const response = $json;

if (response.status === 'error') {
  return {
    json: {
      success: false,
      error: response.message || 'BMS API error',
      answer: null,
      citations: []
    }
  };
}

const answer = response.answer || response.response || '';
const citations = (response.citations || []).map(cit => ({
  document_name: cit.document_name || cit.source,
  document_type: cit.document_type || 'unknown',
  department: cit.department || 'unknown',
  relevance_score: cit.relevance_score || cit.score || 0,
  chunk_index: cit.chunk_index,
  content_preview: (cit.content || '').substring(0, 200),
  document_url: cit.document_url || null,
  processing_profile: cit.processing_profile || 'railway',
  quality_score: cit.quality_score || 0
}));

return {
  json: {
    success: true,
    answer,
    citations,
    metadata: {
      query: response.query,
      confidence: response.confidence || 0,
      chunks_used: response.chunks_used || citations.length,
      generation_time_ms: response.generation_time_ms || 0,
      search_type: 'ask'
    }
  }
};
